1	/**
2	 * Контракт между платформой и играми. Имена фиксированы: на них опираются все игры.
3	 * Игра импортирует из платформы только `platform/sdk/*`.
4	 */
5	
6	/**
7	 * Генератор случайных чисел. `next()` возвращает число в [0, 1). Передаётся игре платформой.
8	 * На каждый вызов `start`/`action` игра получает отдельный замороженный объект; сохранять его между вызовами нельзя.
9	 */
10	export interface Rng {
11	  next(): number;
12	}
13	
14	/**
15	 * Результат шага игры.
16	 * - `continue` — раунд продолжается, нужен следующий ход;
17	 * - `finished` — раунд окончен, `payout` — полная сумма к зачислению (0 при проигрыше).
18	 */
19	export type Step<S> =
20	  | { status: 'continue'; state: S }
21	  | { status: 'finished'; state: S; payout: number };
22	
23	/**
24	 * Серверный модуль игры. Платформа вызывает его внутри раунда: списывает ставку до `start`
25	 * и зачисляет `payout` после шага со статусом `finished`. Игра не знает о кошельке и балансе.
26	 *
27	 * Состояние `S` и параметры `P` должны сериализоваться в JSON: платформа хранит их на диске.
28	 *
29	 * Порядок внутри `start`/`action`: сначала проверить `action` (бросить `INVALID_ACTION`) и всё, что может упасть,
30	 * и только потом обращаться к `rng`. После первого `rng.next()` исключения запрещены, а шаг должен быть корректным:
31	 * иначе повтор хода давал бы новый исход. Если игра всё же упала после `rng.next()`, платформа не возвращает
32	 * ставку и не даёт повторить ход: раунд блокируется для ручного разбора, клиент получает `INTERNAL_ERROR`.
33	 * Если игра упала в `start` до обращения к `rng`, раунд аннулируется, ставка возвращается.
34	 *
35	 * Серверный модуль работает в процессе ядра. Кроме `platform/sdk/*`, ему запрещены `process`, `globalThis`,
36	 * `require`, динамический `import()`, `fetch`, `eval`/`Function` и модули `node:*`: игра — чистая функция от
37	 * `ctx` и состояния.
38	 */
39	export interface GameModule<P = any, S = any, A = any> {
40	  /** Идентификатор игры, совпадает с `id` в `manifest.json`. */
41	  id: string;
42	  /** Проверяет и нормализует параметры раунда. Бросает `GameError('INVALID_PARAMS')`. */
43	  validateParams(params: unknown): P;
44	  /** Начинает раунд (ставка уже списана). */
45	  start(ctx: { bet: number; params: P; rng: Rng }): Step<S>;
46	  /** Ход игрока. Бросает `GameError('INVALID_ACTION')` на недопустимое действие. */
47	  action(ctx: { bet: number; params: P; state: S; action: A; rng: Rng }): Step<S>;
48	  /** Что можно показать клиенту. До конца раунда (`finished = false`) скрытое не раскрывается. */
49	  publicView(state: S, finished: boolean): unknown;
50	}
51	
52	/** Ошибка игры с кодом (`INVALID_PARAMS`, `INVALID_ACTION`). Платформа передаёт код клиенту. */
53	export class GameError extends Error {
54	  /** Код ошибки. */
55	  code: string;
56	
57	  /**
58	   * @param code код ошибки, например `INVALID_PARAMS`
59	   * @param message необязательное пояснение для игрока
60	   */
61	  constructor(code: string, message?: string) {
62	    super(message ?? code);
63	    this.name = 'GameError';
64	    this.code = code;
65	  }
66	}
67

