1	// Приёмочные тесты «Монетки» через тестовую платформу (games/coin/spec.md, SC-1…SC-9).
2	// Поведение проверяется снаружи: ответы startRound/open/action, баланс, журнал транзакций, коды ошибок.
3	import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
4	import game from '../server/index.ts';
5	import { createTestPlatform, fixedRng } from '../../../platform/testkit/index.ts';
6	
7	/** Код ошибки, которую бросает fn; если fn не бросила — тест падает. */
8	function codeOf(fn: () => unknown): string {
9	  try {
10	    const v = fn();
11	    throw new Error(`ожидалась ошибка, а вызов вернул ${JSON.stringify(v)}`);
12	  } catch (e: any) {
13	    if (e instanceof Error && e.message.startsWith('ожидалась ошибка')) throw e;
14	    return e?.code;
15	  }
16	}
17	
18	function platform(rng: number[], startBalance = 100) {
19	  return createTestPlatform({ games: [game], rng: fixedRng(rng), startBalance });
20	}
21	
22	describe('Монетка: раунды через платформу', () => {
23	  beforeEach(() => {
24	    // Исход определяется только переданным rng (spec: «Math.random не используется»).
25	    vi.spyOn(Math, 'random').mockImplementation(() => {
26	      throw new Error('Math.random запрещён в игре');
27	    });
28	  });
29	  afterEach(() => {
30	    vi.restoreAllMocks();
31	  });
32	
33	  it('SC-1: выигрыш на орле — выплата bet × 1.96, раунд закрыт сразу', () => {
34	    const p = platform([0.3]);
35	    const r = p.startRound('coin', 1, { side: 'heads' });
36	    expect(r.gameId).toBe('coin');
37	    expect(r.status).toBe('closed');
38	    expect(r.bet).toBe(1);
39	    expect(r.payout).toBe(1.96);
40	    expect(r.balance).toBe(100.96);
41	    expect(r.view).toEqual({ side: 'heads', outcome: 'heads', win: true });
42	    expect(p.balance()).toBe(100.96);
43	    const txs = p.transactions();
44	    expect(txs).toHaveLength(2);
45	    expect(txs[0]).toMatchObject({ type: 'bet', roundId: r.roundId, amount: 1, balanceAfter: 99 });
46	    expect(txs[1]).toMatchObject({ type: 'payout', roundId: r.roundId, amount: 1.96, balanceAfter: 100.96 });
47	  });
48	
49	  it('SC-2: выигрыш на решке при rng ровно 0.5 и максимальной ставке 10', () => {
50	    const p = platform([0.5]);
51	    const r = p.startRound('coin', 10, { side: 'tails' });
52	    expect(r.status).toBe('closed');
53	    expect(r.bet).toBe(10);
54	    expect(r.payout).toBe(19.6);
55	    expect(r.balance).toBe(109.6);
56	    expect(r.view).toEqual({ side: 'tails', outcome: 'tails', win: true });
57	    expect(p.balance()).toBe(109.6);
58	    const txs = p.transactions();
59	    expect(txs).toHaveLength(2);
60	    expect(txs[0]).toMatchObject({ type: 'bet', amount: 10, balanceAfter: 90 });
61	    expect(txs[1]).toMatchObject({ type: 'payout', amount: 19.6, balanceAfter: 109.6 });
62	  });
63	
64	  it('SC-3: проигрыш — выплата 0, ставка потеряна, раунд закрыт выплатой 0', () => {
65	    const p = platform([0.7]);
66	    const r = p.startRound('coin', 5, { side: 'heads' });
67	    expect(r.status).toBe('closed');
68	    expect(r.bet).toBe(5);
69	    expect(r.payout).toBe(0);
70	    expect(r.balance).toBe(95);
71	    expect(r.view).toEqual({ side: 'heads', outcome: 'tails', win: false });
72	    expect(p.balance()).toBe(95);
73	    const txs = p.transactions();
74	    expect(txs).toHaveLength(2);
75	    expect(txs[0]).toMatchObject({ type: 'bet', amount: 5, balanceAfter: 95 });
76	    expect(txs[1]).toMatchObject({ type: 'payout', amount: 0, balanceAfter: 95 });
77	  });
78	
79	  it('SC-4: проигрыш у границы — rng 0.4999 даёт орла, ставка на решку проигрывает', () => {
80	    const p = platform([0.4999]);
81	    const r = p.startRound('coin', 2, { side: 'tails' });
82	    expect(r.status).toBe('closed');
83	    expect(r.view).toEqual({ side: 'tails', outcome: 'heads', win: false });
84	    expect(r.payout).toBe(0);
85	    expect(r.balance).toBe(98);
86	    expect(p.balance()).toBe(98);
87	    expect(p.transactions().map((t) => [t.type, t.amount, t.balanceAfter])).toEqual([
88	      ['bet', 2, 98],
89	      ['payout', 0, 98],
90	    ]);
91	  });
92	
93	  it('SC-4: граница с другой стороны — rng 0.4999 при ставке на орла выигрывает', () => {
